UPDATE courses SET
    course_description = '<h4>Course Structure</h4><div id="brxe-faepxw"><div data-script-id="tjlpew" id="brxe-tjlpew"><div id="brxe-mblofe"><div id="brxe-uzlpsb"><h5>Year 1</h5><i id="brxe-qzziab"></i></div><div><div><p><strong>YEAR 1, SEMESTER 1</strong></p> <hr/> <ul> <li>AC400 Agribusiness Accounting</li> <li>BC400 Communication and Media Management</li> <li>EC400 Agribusiness Economics and Finance</li> <li>MK400 Agribusiness Marketing</li> </ul> <p><strong>YEAR 1, SEMESTER 2</strong></p> <hr/> <ul> <li>AP501 Food, Fibre, and Protein Production</li> <li>IM401 Introduction to Agroinformatics</li> <li>IM501 Agriculture Data and Information Management</li> <li>MG401 Leadership in Agribusiness</li> </ul> </div></div></div><div id="brxe-jrqhyb"><div id="brxe-qpsdeo"><h5>Year 2</h5><i id="brxe-fhvtui"></i></div><div><div><p><strong>YEAR 2, SEMESTER 1</strong></p> <hr/> <ul> <li>AP511 Precision Agriculture</li> <li>RS501 Research Methodology 2 x electives</li> </ul> <p><strong>YEAR 2, SEMESTER 2</strong></p> <hr/> <ul> <li>IM502 Big Data in Agriculture</li> <li>IM500 Agroinformatics Capstone 2 x electives</li> </ul> </div></div></div><div id="brxe-shmwpm"><div id="brxe-fxclji"><h5>Year 3</h5><i id="brxe-odwtbx"></i></div><div><div></div></div></div></div></div><h4>Year 1</h4><div><div><p><strong>YEAR 1, SEMESTER 1</strong></p> <hr/> <ul> <li>AC400 Agribusiness Accounting</li> <li>BC400 Communication and Media Management</li> <li>EC400 Agribusiness Economics and Finance</li> <li>MK400 Agribusiness Marketing</li> </ul> <p><strong>YEAR 1, SEMESTER 2</strong></p> <hr/> <ul> <li>AP501 Food, Fibre, and Protein Production</li> <li>IM401 Introduction to Agroinformatics</li> <li>IM501 Agriculture Data and Information Management</li> <li>MG401 Leadership in Agribusiness</li> </ul> </div></div><h4>Year 2</h4><div><div><p><strong>YEAR 2, SEMESTER 1</strong></p> <hr/> <ul> <li>AP511 Precision Agriculture</li> <li>RS501 Research Methodology 2 x electives</li> </ul> <p><strong>YEAR 2, SEMESTER 2</strong></p> <hr/> <ul> <li>IM502 Big Data in Agriculture</li> <li>IM500 Agroinformatics Capstone 2 x electives</li> </ul> </div></div>',
    total_course_duration = '2 years',
    offshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Admission Requirements</h4><div id="brxe-ftutfr"><div><h3>General</h3> <p>All applicants must meet the minimum English language requirements. These are specified</p> <p>In addition, all applicants must meet either: relevant standard minimum entry requirements as specified below or alternative relevant standard minimum entry requirements.</p> <p>Applicants who apply for admission to a course on the basis of an approved guaranteed pathway, will be offered a place in that course provided they meet the requirements specified for entry.</p> <h3>Domestic students</h3> <p>Admission to undergraduate courses is based on successful completion of one of the following:</p> <ul> <li>The Queensland Higher School Certificate or an interstate equivalent HigherSchool Certificate. OP 17 / ATAR 60</li> <li>Completion of the International Baccalaureate Diploma.</li> <li>Completion of an approved course at the level of Diploma or Advanced Diploma at a TAFE or registered training organisation (RTO).</li> <li>Possession of qualifications deemed equivalent to any of the above qualifications.</li> </ul> <h3>International students</h3> <p>International students who have not completed an Australian qualification must have appropriate educational qualifications, deemed equivalent to the Australian Higher School Certificate under the NOOSR guidelines</p> <p>International candidates may also be considered for admission by:</p> <ul> <li>Satisfactorily completing vocational and or tertiary studies in Australia oroverseas, accredited under the Australian Qualifications Framework (AQF), or</li> <li>Satisfactorily completing equivalent overseas studies</li> </ul> <p>Students enrolling from non-English speaking countries are required to undertake an English language test and demonstrate English proficiency with a minimum score of:</p> <ul> <li>IELTS (Academic): Minimum overall 6.5 bands with no module less than 6.0 bands</li> <li>PTE: Minimum overall score of 59 with no module less than 51</li> <li>TOEFL (paper based) Minimum overall score of 79 with no module less than 60</li> </ul> <p>It is expected that students can demonstrate that the English language test was successfully completed within two years of the date of application for admission.</p> <p>Note: International students must hold a valid student visa. There are numerous conditions that apply to a student visa. In particular, a holder of a student visa may not work, paid or unpaid, for more than 40 hours in any fortnight during semester time. Where Work Integrated Learning is integrated into a course, it does not count towards the 40 hours. Current information on student visa conditions may be found at <a href="https://homeaffairs.gov.au/Trav/stud/more/Visa-conditions/visaconditions-students" rel="noopener" target="_blank">https://homeaffairs.gov.au/Trav/stud/more/Visa-conditions/visaconditions-students</a></p> <h3>Alternative entry</h3> <p>Applicants who do not meet the minimum requirements for entry to a course of study, may be considered for alternative entry on the basis of higher education study equivalent to at least two units of study successfully completed at a registered Australian higher education institution or an overseas educational institution assessed as being equivalent by LeadersInstitute.</p> <p>A person may also be considered for entry on the basis of recognition of prior learning, prior employment in a relevant field or the acquisition of a non-award qualification in a relevant field.</p> <p>Applicants seeking alternative entry must also fulfil the English language entry requirements.</p> </div></div>',
    apply_form = 'https://leaders.edu.au/courses/master-of-agricultural-information-management-2/',
    updated_at = NOW()
WHERE cricos_course_code = '111900F';
UPDATE courses SET
    course_description = '<h4>Course Rationale</h4><div id="brxe-dzspya"><div><p>The Master of Agricultural Information Management (MAI) is a two-year post graduate program requiring a relevant undergraduate degree for entry. This program explores the high level of innovation and technology currently being employed in the agriculture sector. The United Nations Sustainable Development Goal number two is to “end hunger, achieve food security and improved nutrition, and promote sustainable agriculture.” Estimates by the Food and Agriculture Organization (FAO) show that by 2050, global demand for food will rise by 50% compared to the present.</p> <p>Pressure on existing food systems is advancing because of an increasing world population creating the need to approach this problem innovatively. Estimates show that using current and emerging technologies, the overall demand for food will be met, but questions still linger whether it will be in a sustainable manner. Emerging and current technological innovations could be used as a lever to address these challenges and further enable improvements in food systems, productivity, and human welfare.</p> <p>New technology will play a crucial role in moving the world to a more productive path. Technological advancement in analytics, artificial intelligence, information and communication technology, seed and food bioengineering and robotics present innovative opportunities for producing food in smarter ways. However, technological advancements are not enough, and other factors need to be present for there to be success, including public sector governance, workforce development, trade and tax policies, and business regulation.</p> <p>Today, data capture and mechanisation are increasingly relevant in the management and production of crops, animals, and the natural environment. This emerging industry targets individuals who are dedicated to pursuing a career in agriculture or entrepreneurial minds who want to harness gains in agriculture.</p> <p>As a result, there is a growing need for professionals who are qualified and well versed with these new and emerging technologies to take over this niche and contribute to supporting the food systems of the 21st century and beyond. The Master of Agricultural Information Management is conceptualised and designed to produce graduates who have skills and an in-depth understanding of the application of information technology (IT) in the analysis of agricultural data and management decision-making, and as a result harness the vast opportunities in agriculture while also responding to the different challenges and constraints facing the sector.</p> <p>Expertise accrued during the course include the usage of agribusiness management, geospatial technologies, financial management, creation of data maps, agricultural economics, and enhanced computer skills related to data computation, processing, and analysis. This expertise aims to address management of agricultural information and agribusiness enterprises.</p> <p>Graduates will have developed and applied theoretical knowledge and understanding from a variety of authentic learning tasks and assessments, including lectures, guest lecturers, workshops, computer lab sessions, group work, and industry visits. Assessments will be in the form of case studies, formal examinations and projects that reflect real-life situations.</p> <p>The course encourages all graduates to be advocates of lifelong learning and ethical practice through membership of professional associations and industry peak bodies. Career pathways include but are not limited to:</p> <ul> <li>Agroinformatics consultant</li> <li>Agribusiness consultant</li> <li>Agricultural marketing specialist</li> <li>Agriculture development officer</li> <li>Supply chain manager</li> <li>University academic</li> <li>Employment in relevant government departments in areas such as research, regulation, policy development, education and extension, and administration</li> <li>Employment in private sector organisations providing services to the agribusiness sector in areas such as research, extension, administration, and sales</li> <li>Employment in industry</li> </ul> </div></div><h4>Course Structure</h4><div id="brxe-faepxw"><div data-script-id="tjlpew" id="brxe-tjlpew"><div id="brxe-mblofe"><div id="brxe-uzlpsb"><h5>Year 1</h5><i id="brxe-qzziab"></i></div><div><div></div></div></div><div id="brxe-jrqhyb"><div id="brxe-qpsdeo"><h5>Year 2</h5><i id="brxe-fhvtui"></i></div><div><div></div></div></div><div id="brxe-shmwpm"><div id="brxe-fxclji"><h5>Year 3</h5><i id="brxe-odwtbx"></i></div><div><div></div></div></div></div><div><p>The course structure is based on four semesters (each semester is 12 teaching weeks, plus one review week and one exam week).</p> <ul> <li>120 credit points of core</li> <li>40 credit points of elective</li> </ul> <p>To qualify for award of Master of Agricultural Information Management a student shall accrue an aggregate of at least 160 credit points, including satisfactory completion of the core units noted below.</p> <p><strong>YEAR 1, SEMESTER 1</strong></p> <ul> <li><a href="https://leaders.edu.au/units/ac400-agribusiness-accounting/">AC400 Agribusiness Accounting</a></li> <li><a href="https://leaders.edu.au/units/bc400-communication-and-media-management/">BC400 Communication and Media Management</a></li> <li><a href="https://leaders.edu.au/units/ec400-agribusiness-economics-and-finance/">EC400 Agribusiness Economics and Finance</a></li> <li><a href="https://leaders.edu.au/units/mk400-agribusiness-marketing/">MK400 Agribusiness Marketing</a></li> </ul> <p><strong>YEAR 1, SEMESTER 2</strong></p> <ul> <li><a href="https://leaders.edu.au/units/ap501-food-fibre-and-protein/">AP501 Food, Fibre, and Protein Production</a></li> <li><a href="https://leaders.edu.au/units/im401-introduction-to-agroinformatics/">IM401 Introduction to Agroinformatics</a></li> <li><a href="https://leaders.edu.au/units/im501-agricultural-data-and-information-management/">IM501 Agriculture Data and Information Management</a></li> <li><a href="https://leaders.edu.au/units/mg401-leadership-in-agribusiness/">MG401 Leadership in Agribusiness</a></li> </ul> <p><strong>YEAR 2, SEMESTER 1</strong></p> <ul> <li><a href="https://leaders.edu.au/units/ap511-precision-agriculture/">AP511 Precision Agriculture</a></li> <li><a href="https://leaders.edu.au/units/rs501-research-methodology/">RS501 Research Methodology</a></li> </ul> <p>2 x electives</p> <p><strong>YEAR 2, SEMESTER 2</strong></p> <ul> <li><a href="https://leaders.edu.au/units/im502-big-data-in-agriculture-2/">IM502 Big Data in Agriculture</a></li> <li><a href="https://leaders.edu.au/units/im500-agroinformatics-capstone/">IM500 Agroinformatics Capstone</a></li> </ul> <p>2 x electives</p> <p> </p> <p><strong>More Information</strong></p> <p>For more information about elective units see the <a href="https://leaders.edu.au/units/">List of Units</a>.</p> </div></div><h4>Learning Outcomes</h4><div id="brxe-lxrwpc"><div><p>Graduates of the Master of Agricultural Information Management will:</p> <ul> <li>integrate contemporary business decisions and information technology in multiple agribusiness contexts;</li> <li>create knowledge through the application of current theory and methods;</li> <li>demonstrate a clear understanding of ethical issues relevant to agricultural information application and communication;</li> <li>critically analyse and evaluate large volumes of data, demonstrating mastery of theoretical knowledge in professional practice, to support decision making;</li> <li>apply appropriate procedures for packaging and re-packaging agricultural information to adapt to diverse needs of agribusiness;</li> <li>lead their clients/organisations to recognise the opportunities and capabilities that ICT offers;</li> <li>apply cognitive skills, with high level personal autonomy and accountability, to undertake research, to analyse and evaluate contemporary multidisciplinary practice for the development and improvement of agricultural information management;</li> <li>apply current international standards and best practices to provide leadership in adoption of agricultural information management principles;</li> <li>develop and demonstrate highly effective communication and interpersonal skills, autonomy, critical thinking, and creativity as a practitioner and to be able to transfer complex knowledge and ideas to specialist and non-specialist audiences.</li> </ul> </div></div>',
    total_course_duration = '2 years',
    offshore_tuition_fee = 50000,
    enrolment_fee = 500,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><div id="brxe-odnbib"><div><p><strong>Domestic Students</strong></p> <p>Completion of an AQF Level 7 or above higher education qualification (or overseas equivalent) with a minimum GPA of 4.5 (using a 7.0 point scale) in Agriculture, Food Science, Business, Management, or IT/ICT;</p> <p><strong>OR</strong></p> <p>Completion of an AQF Level 7 or above higher education qualification (or overseas equivalent) with a minimum GPA of 4.5 (using a 7.0 point scale) in any field <span>AND</span> a minimum two years’ professional experience in a managerial position.</p> <p><strong>International Students</strong></p> <p>Completion of an AQF Level 7 or above higher education qualification (or overseas equivalent) with a minimum GPA of 4.5 (using a 7.0 point scale) in Agriculture, Food Science, Business, Management, or IT/ICT;</p> <p><strong>OR</strong></p> <p>Completion of an AQF Level 7 or above higher education qualification (or overseas equivalent) with a minimum GPA of 4.5 (using a 7.0 point scale) in any field AND a minimum two years’ professional experience in a managerial position.</p> <p>Applicants whose entry qualifications were obtained in an institution where English is not the language of instruction normally require an International English Language Testing Service (IELTS) of 6.5, with a score of not less than 6.0 in any of the four skill areas, or equivalent.</p> <p>Note: International students must hold a valid student visa. There are numerous conditions that apply to a student visa. A holder of a student visa may not work, paid or unpaid, for more than 40 hours in any fortnight during semester. Current information on student visa conditions may be found here.</p> <p><strong>Relevant Work Experience</strong></p> <p>The following supporting documentation is required to demonstrate relevant work experience:</p> <ul> <li>certified copies of relevant qualificiations or micro-credentials completed, if relevant;</li> <li>a current CV demonstrating relevant work experience, including managerial or leadership experience of people or projects. This includes a full work history that details the major activities undertaken, such as managing a team, managerial components of major projects, and/or delegation responsibilities;</li> <li>two current, signed references that are work related; and</li> <li>Statement of Intent outlining the motivation to study, previous education, employment history; and how this course can assist in career aspiration or progression.</li> </ul> <p>Applicants entering with two years of professional experience are evaluated on a case-by-case basis by the Program Director (or delegated representative).</p> <p><strong>Credit and Recognition of Prior Learning (RPL)</strong></p> <p>Credit for previous learning may be obtained through the process of articulation, credit transfer, and RPL or a combination of these processes. Students who wish to apply for RPL must provide evidence in terms of completed qualifications along with other relevant documentation.</p> <p><strong>Alternative Admission Arrangements</strong></p> <p>Alternative admission pathways are also open for educationally disadvantaged applicants and for First Nations Peoples applicants. These applicants will be assessed on a case-by-case basis with RPL, professional accreditations, and the provision of a portfolio of work for entry to micro-credential and single units.</p> <p>Applicants seeking alternative entry must also fulfil the English language entry requirements.</p> <p>Alternative pathways are evaluated on a case-by-case basis by the Program Director (or delegated representative).</p> </div></div>',
    apply_form = 'https://leaders.edu.au/courses/master-of-agricultural-information-management/',
    updated_at = NOW()
WHERE cricos_course_code = '111899F';
UPDATE courses SET
    course_description = '<h4>Course Rationale</h4><div id="brxe-rtcirv"><div><p>Australia is a world leader in sustainable agriculture and production of food and fibre. Inadequate production and uneven distribution of food has lately become a high priority global concern regarding food security. This, coupled with changing global norms reflected in World Trade Organisation (WTO) rulings, increased global competitiveness, and more recently the COVID-19 pandemic invites a tremendous need for professional courses in Agribusiness, and makes it one of the most challenging and exciting sectors to be in. Globally, there is a severe a shortage of agribusiness professionals. The Leaders Institute’s MBA (Agribusiness) is ideally placed to prepare professionals in the field of Agribusiness.</p> <p>A field as vast and important as agribusiness has wide range of career prospects. The Leaders Institute MBA in Agribusiness will help students to reap satisfying employment outcomes and make valuable contributions to the sector, given its challenges and opportunities. This course emphasises participating in advancements and management of agribusiness. The focus is on the sustainability and the knowledge acquired by the graduate revolves around the business of agriculture ‘from farm to fork’. The topics involved explore the innovative strategies that can be employed to achieve the objective of sustainable food and fibre production, processing, and distribution.</p> <p>The MBA (Agribus) is designed to meet the needs of students who are interested in careers with agricultural input supply, agricultural production, commodity assembly and processing, agricultural marketing organizations, and agricultural technology. Graduates will be equipped with the knowledge, understanding and skills, that will make them market- and-business ready to work in small and large businesses in the functions of agribusiness management. Graduates will also be equipped to be self-employed and to establish their own businesses and employ others.</p> <p>The course encourages all graduates to be advocates of lifelong learning and ethical practice through membership of professional associations and industry peak bodies.</p> <p>The objective of the course is to transform the students into graduates who are competent professional agribusiness managers across the value chain that spans from ‘farm to fork’, across scales from the local community to global market. Career pathways may include but are not limited to:</p> <ul> <li>Farm management</li> <li>Agribusiness management</li> <li>Agriculture and resource economy</li> <li>Sales and marketing of agribusiness input and outputs</li> <li>Rural banking and rural finance</li> <li>Agricultural consultancy service</li> <li>Research centres</li> <li>Government and non-government organisations including government departments and research establishments, universities, industry marketing and research organisations, representative and peak bodies, and multilateral agencies.</li> </ul> </div></div><h4>Course Structure</h4><div id="brxe-lxddle"><div data-script-id="yjhrjq" id="brxe-yjhrjq"><div id="brxe-dwjsxm"><div id="brxe-bvwexi"><h5>Year 1</h5><i id="brxe-gkkngn"></i></div><div><div></div></div></div><div id="brxe-wpavce"><div id="brxe-knbhhi"><h5>Year 2</h5><i id="brxe-uqqizr"></i></div><div><div></div></div></div><div id="brxe-nqcdkn"><div id="brxe-svdhxz"><h5>Year 3</h5><i id="brxe-mkbspd"></i></div><div><div></div></div></div></div><div><p>The course structure is based on four semesters (each semester is 12 teaching weeks, plus one review week and one exam week).</p> <ul> <li>120 credit points of core</li> <li>40 credit points of elective</li> </ul> <p>To qualify for award of Master of Business Administration (Agribusiness) a student shall accrue an aggregate of at least 160 credit points, including satisfactory completion of the core units noted below.</p> <p><strong>YEAR 1, SEMESTER 1</strong></p> <ul> <li><a href="https://leaders.edu.au/units/bc400-communication-and-media-management/">BC400 Communication and Media Management</a></li> <li><a href="https://leaders.edu.au/units/ec400-agribusiness-economics-and-finance/">EC400 Agribusiness Economics and Finance</a></li> <li><a href="https://leaders.edu.au/units/mg401-leadership-in-agribusiness/">MG401 Leadership in Agribusiness</a></li> <li><a href="https://leaders.edu.au/units/mk400-agribusiness-marketing/">MK400 Agribusiness Marketing</a></li> </ul> <p><strong>YEAR 1, SEMESTER 2</strong></p> <ul> <li><a href="https://leaders.edu.au/units/ac400-agribusiness-accounting/">AC400 Agribusiness Accounting</a></li> <li><a href="https://leaders.edu.au/units/ap501-food-fibre-and-protein/">AP501 Food, Fibre, and Protein</a></li> <li><a href="https://leaders.edu.au/units/ec501-international-economic-development/">EC501 International Economic Development</a></li> <li><a href="https://leaders.edu.au/units/im401-introduction-to-agroinformatics/">IM401 Introduction to Agroinformatics</a></li> </ul> <p><strong>YEAR 2, SEMESTER 1</strong></p> <ul> <li><a href="https://leaders.edu.au/units/mg502-agribusiness-strategic-management/">MG502 Agribusiness Strategic Management</a></li> <li><a href="https://leaders.edu.au/units/rs501-research-methodology/">RS501 Research Methodology</a></li> </ul> <p>2 x electives</p> <p><strong>YEAR 2, SEMESTER 2</strong></p> <ul> <li><a href="https://leaders.edu.au/units/ab500-agribusiness-capstone/">AB500 Agribusiness Capstone</a></li> <li><a href="https://leaders.edu.au/units/mg501-value-chain-management-in-agribusiness/">MG501 Value Chain Management in Agribusiness</a></li> </ul> <p>2 x electives</p> <p><strong>More Information</strong></p> <p>For more information about elective units see the <a href="https://leaders.edu.au/units/">List of Units.</a></p> </div></div><h4>Learning Outcomes</h4><div id="brxe-evgoru"><div><p>Graduates of the Master of Business Administration (Agribusiness) will:</p> <ul> <li>synthesise and apply the requisite knowledge, including research principles and methods, skills and attitudes for managerial decision making and implementation in the unique context of agribusiness;</li> <li>demonstrate the integration of modern business decisions and information technology into daily business challenges;</li> <li>develop entrepreneurial capabilities to make them effective change agents in agribusiness;</li> <li>develop and demonstrate highly effective communication and interpersonal skills, autonomy, critical thinking, and creativity as a practitioner and to be able to transfer complex knowledge and ideas to a variety of audiences;</li> <li>create innovative solutions for complex agribusiness management issues that demonstrate mastery of theoretical knowledge and reflect professional practice;</li> <li>develop capabilities to become leaders and nurture in them a commitment for integrity, ethics, and social purpose;</li> <li>apply principles of sustainability to agribusiness practices;</li> <li>benchmark best management practices to understand agribusiness locally and globally by planning and implementing learnings in various projects and research activities.</li> </ul> </div></div>',
    total_course_duration = '2 years',
    offshore_tuition_fee = 50000,
    enrolment_fee = 500,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><div id="brxe-yhpyve"><div><p><strong>Domestic Students</strong></p> <p>Completion of an AQF Level 7 or above higher education qualification (or overseas equivalent) with a minimum GPA of 4.5 (using a 7.0 point scale) in Agriculture, Food, Business, Management, or IT/ICT;</p> <p>OR</p> <p>Completion of an AQF Level 7 or above higher education qualification (or overseas equivalent) with a minimum GPA of 4.5 (using a 7.0 point scale) in any field AND a minimum two years’ professional experience in a managerial position.</p> <p>Applicants whose entry qualifications were obtained in an institution where English is not the language of instruction normally require an International English Language Testing Service (IELTS) of 6.5, with a score of not less than 6.0 in any of the four skill areas, or equivalent.</p> <p>Note: International students must hold a valid student visa. There are numerous conditions that apply to a student visa. A holder of a student visa may not work, paid or unpaid, for more than 40 hours in any fortnight during semester. Current information on student visa conditions may be found here.</p> <p><strong>Relevant Work Experience</strong></p> <p>The following supporting documentation is required to demonstrate relevant work experience:</p> <ul> <li>certified copies of relevant qualificiations or micro-credentials completed, if relevant;</li> <li>a current CV demonstrating relevant work experience, including managerial or leadership experience of people or projects. This includes a full work history that details the major activities undertaken, such as managing a team, managerial components of major projects, and/or delegation responsibilities;</li> <li>two current, signed references that are work related; and</li> <li>Statement of Intent outlining the motivation to study, previous education, employment history; and how this course can assist in career aspiration or progression.</li> </ul> <p>Applicants entering with two years of professional experience are evaluated on a case-by-case basis by the Program Director (or delegated representative).</p> <p><strong>Credit and Recognition of Prior Learning (RPL)</strong></p> <p>Credit for previous learning may be obtained through the process of articulation, credit transfer, and RPL or a combination of these processes. Students who wish to apply for RPL must provide evidence in terms of completed qualifications along with other relevant documentation.</p> <p><strong>Alternative Admission Arrangements</strong></p> <p>Alternative admission pathways are also open for educationally disadvantaged applicants and for First Nations Peoples applicants. These applicants will be assessed on a case-by-case basis with RPL, professional accreditations, and the provision of a portfolio of work for entry to micro-credential and single units.</p> <p>Applicants seeking alternative entry must also fulfil the English language entry requirements.</p> <p>Alternative pathways are evaluated on a case-by-case basis by the Program Director (or delegated representative).</p> </div></div>',
