UPDATE courses SET
    course_description = '<h4>Course Rationale</h4><div id="brxe-ndlopk"><div><p>The Master of Research is a Higher Degree Research (HDR) course designed to provide graduates with an advanced and integrated body of knowledge in their field of expertise.</p> <p>Graduates will be equipped with systematic and advanced knowledge and skills in research methods, critical thinking, communication, and creative problem solving in complex business settings. Through independent research, students identify, investigate, and address a complex challenge in their area of business management, organisation management, of farm management and agribusiness. Students will present findings, demonstrating an original contribution to the business sector.</p> </div></div><h4>Course Structure</h4><div id="brxe-cbyglf"><div data-script-id="wtnaht" id="brxe-wtnaht"><div id="brxe-celvxg"><div id="brxe-zahxfe"><h5>Year 1</h5><i id="brxe-oxdgfa"></i></div><div><div></div></div></div><div id="brxe-rvcgah"><div id="brxe-cvvgbj"><h5>Year 2</h5><i id="brxe-jmczkm"></i></div><div><div></div></div></div><div id="brxe-eoslme"><div id="brxe-tzdnrz"><h5>Year 3</h5><i id="brxe-xswcyn"></i></div><div><div></div></div></div></div><div><p><strong>Core Coursework Units</strong><br/> RS701 Business Research Fundamentals<br/> RS702 Literature Review for Publication<br/> RS703 Advanced Business Research Methods<br/> RS704 Research Proposal and Seminar</p> <p><strong>Core Research Component</strong><br/> RS710 Masters Research</p> <p>The course structure is based on four semesters (each semester is 12 teaching weeks, plus one review week and one study week).</p> <ul> <li>4 x core research units (40 credit points)</li> <li>1 x 30,000-word Thesis or equivalent portfolio of work (120 credit points)</li> </ul> <p> </p> <p>To qualify for the award of Master of Research a candidate shall accrue an aggregate of at least 160 credit points, including satisfactory completion of the core units.</p> </div></div><h4>Learning Outcomes</h4><div id="brxe-javndu"><div><ul> <li>Demonstrate detailed understanding of key concepts, theories, and methods related to business research</li> <li>Select and apply appropriate research methodologies to provide solutions to business problems</li> <li>Work independently to integrate ethical decision making in business research</li> <li>Communicate as a business leader to transfer complex knowledge and creative ideas to specialist and non-specialist audiences</li> <li>Autonomously plan and execute a research thesis/portfolio</li> </ul> </div></div>',
    total_course_duration = '2 years',
    offshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><div id="brxe-xgfpkk"><div><p>Completion of an AQF Level 8 Bachelor Honours 2A (or overseas equivalent) in a relevant business field as determined by the Program Director (or delegated representative);</p> <p>OR</p> <p>Completion of an AQF Level 9 Masters by coursework degree (or overseas equivalent) in a relevant business field as determined by the Program Director (or delegated representative).</p> <p><strong>International Students</strong></p> <p>International students who have not completed an Australian qualification must have appropriate educational qualifications, deemed equivalent under the NOOSR guidelines.</p> <p>International students whose entry qualifications were obtained in an institution where English is not the language of instruction normally require an International English Language Testing Services (IELTS) of 6.5, with a score of not less than 6.0 in any of the four skill areas, or equivalent. It is expected that students can demonstrate that the English language test was successfully completed within two years of the date of application for admission.</p> <p>Note: International students must hold a valid student visa. There are numerous conditions that apply to a student visa. A holder of a student visa may not work, paid or unpaid, for more than 40 hours in any fortnight during semester. Current information on student visa conditions may be found <a href="https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500" rel="noopener" target="_blank">here</a>.</p> <p><strong>Alternative Admission Arrangements</strong></p> <p>Alternative admission pathways are also open for educationally disadvantaged applicants and for First Nations Peoples applicants. These applicants will be assessed on a case-by-case basis. Applicants seeking alternative entry must also fulfil the English language entry requirements.</p> <p>For more information regarding how to apply for a Higher Degree Research, please see: <a href="https://leaders.edu.au/your-research/">Your Research</a></p> </div></div>',
    apply_form = 'https://leaders.edu.au/courses/master-of-research/',
    updated_at = NOW()
WHERE cricos_course_code = '120200E';
